d = os.environ.get('RLM_SESSION_DIR', '')
if d:
    t = open(d + '/../../sessions/' + os.path.basename(d) + '.jsonl').read()
else:
    t = ""

import re

G = {}
for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', t):
    k, h, w = m[1], int(m[2]), int(m[3])
    rest = t[m.end():].split('\n')[:h]
    if k not in G and rest:
        try:
            rows = [[int(x) for x in r.split()] for r in rest if r.strip()]
            G[k] = rows
        except:
            pass

print("Keys:", sorted(G.keys()))
print("\n=== Demo pair 1 ===")
demo_in = G.get('Demo pair 1 input')
demo_out = G.get('Demo pair 1 output')
if demo_in and demo_out:
    print("Input shape:", len(demo_in), "x", len(demo_in[0]))
    print("Output shape:", len(demo_out), "x", len(demo_out[0]))
    # Show first few rows of both
    for i in range(min(5, len(demo_in))):
        print(f"Input row {i}: {demo_in[i]}")
    for i in range(min(5, len(demo_out))):
        print(f"Output row {i}: {demo_out[i]}")

