        if v > 0:
            if v == 9 and w == 2:
                pass  # expected
            elif v == 9 and w == 0:
                print(f"Mismatch at ({i},{j}): {v}->{w}")

# Analyze which cells changed from 9 to 0
changed_to_zero = []
for i in range(len(demo_in)):
    for j in range(len(demo_in[0])):
        if demo_in[i][j] == 9 and demo_out[i][j] == 0:
            changed_to_zero.append((i, j))
            print(f"Changed to zero at ({i},{j})")

# Check connectivity - does each 9 connect to another 9 via 4-connectivity?
def get_neighbors(r, c, rows):
    neighs = []
    for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
        nr, nc = r + dr, c + dc
        if 0 <= nr < len(rows) and 0 <= nc < len(rows[0]):
            if rows[nr][nc] == 9 or demo_out[nr][nc] == 0:  # check both input and output
                neighs.append((nr, nc))
    return neighs

# Actually let's think differently - in the OUTPUT grid, which cells with value 2 
# are connected to form groups vs isolated?
print("\n=== Checking connectivity of output 2s ===")
for i in range(len(demo_out)):
    for j in range(len(demo_out[0])):
        if demo_out[i][j] == 2:
            # Count how many orthogonally adjacent 2s exist
            count = 0
