                    if demo_out[nr][nc] == 2:
                        count += 1
            print(f"Output ({i},{j}) has {count} neighbor(s)")

# Check connectivity in INPUT grid for all 9s
def is_connected_to_another_9(r, c, rows):
    """Check if this 9 is orthogonally connected to at least one other 9"""
    for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
        nr, nc = r + dr, c + dc
        if 0 <= nr < len(rows) and 0 <= nc < len(rows[0]):
