# Let me check vertical/horizontal "isolation" more carefully
# Maybe the rule is about being alone in its row/column segment?

print("=== Checking if cells are isolated in their contiguous segments ===")

def get_contiguous_segment(r, c, rows, include_diag=False):
    """Get all cells in the contiguous segment containing (r,c)"""
    visited = set()
    stack = [(r, c)]

    while stack:
        curr_r, curr_c = stack.pop()
        if (curr_r, curr_c) in visited:
            continue
        visited.add((curr_r, curr_c))

        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
            nr, nc = curr_r + dr, curr_c + dc
            if 0 <= nr < len(rows) and 0 <= nc < len(rows[0]):
                if rows[nr][nc] == 9:
                    stack.append((nr, nc))

    return list(visited)

