def solve_v7(input_grid):
    h, w = len(input_grid), len(input_grid[0])

    nz = [(r,c) for r in range(h) for c in range(w) if input_grid[r][c]==9]

    visited = set()
    comps = []
    for r,c in sorted(nz):
        if (r,c) not in visited:
            comp = []
            stack = [(r,c)]
            while stack:
                cr, cc = stack.pop()
                if (cr,cc) in visited: continue
                visited.add((cr,cc))
                comp.append((cr,cc))

                for dr,dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                    nr, nc = cr+dr, cc+dc
                    if 0 <= nr < h and 0 <= nc < w and input_grid[nr][nc]==9:
                        if (nr,nc) not in visited:
                            stack.append((nr,nc))
            comps.append(comp)

    output = [[0]*w for _ in range(h)]

    for comp in comps:
        n = len(comp)

        if n == 1:
            r,c = comp[0]
            output[r][c] = 2

        elif n == 2:
            cells_sorted = sorted(comp)
            same_col = cells_sorted[0][1] == cells_sorted[1][1]

            if same_col:
                output[cells_sorted[0][0]][cells_sorted[0][1]] = 0
                output[cells_sorted[1][0]][cells_sorted[1][1]] = 2
            else:
                for r,c in comp:
                    output[r][c] = 2

        else:
            deg = {c: sum(1 for o in comp if abs(o[0]-c[0])+abs(o[1]-c[1])==1) for c in comp}
            corner = [c for c in comp if deg[c] == 2][0]
            eps = sorted([c for c in comp if deg[c] == 1])

            def score(ep):
                r,c = ep
                for o in comp:
                    if o != ep and abs(o[0]-r)+abs(o[1]-c)==1:
                        dr, dc = o[0]-r, o[1]-c
                        s = 0
                        if dr > 0: s += 2
                        if dc > 0: s += 1
                        return s
                return 99

            best_ep = min(eps, key=score)

            for r,c in comp:
                if (r,c) != best_ep:
                    output[r][c] = 2

    return output

