def solve_by_value(input_grid):
    """Solve by treating each non-zero value separately"""
    h, w = len(input_grid), len(input_grid[0])

    # Get unique non-zero values
    vals = sorted(set(v for row in input_grid for v in row if v != 0))

    output = [[0]*w for _ in range(h)]

    for val in vals:
        # Find all cells with this value
        positions = [(r,c) for r in range(h) for c in range(w) if input_grid[r][c]==val]

        if not positions:
            continue

        # Build components using 4-connectivity
        visited = set()
        comps = []
        for r,c in sorted(positions):
            if (r,c) not in visited:
                comp = []
                stack = [(r,c)]
                while stack:
                    cr, cc = stack.pop()
                    if (cr,cc) in visited: continue
                    visited.add((cr,cc))
                    comp.append((cr,cc))

                    for dr,dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                        nr, nc = cr+dr, cc+dc
                        if 0 <= nr < h and 0 <= nc < w:
                            if input_grid[nr][nc]==val and (nr,nc) not in visited:
                                stack.append((nr,nc))
                comps.append(comp)

        # Transform each component
        for comp in comps:
            n = len(comp)

            if n == 1:
                r,c = comp[0]
                output[r][c] = 2

            elif n == 2:
                cells_sorted = sorted(comp)
                same_col = cells_sorted[0][1] == cells_sorted[1][1]

                if same_col:
                    # Vertical pair: remove top
                    output[cells_sorted[0][0]][cells_sorted[0][1]] = 0
                    output[cells_sorted[1][0]][cells_sorted[1][1]] = 2
                else:
                    # Horizontal pair: keep both
                    for r,c in comp:
                        output[r][c] = 2

            else:
                # Size-3+: find endpoints, remove least preferred
                deg = {c: sum(1 for o in comp if abs(o[0]-c[0])+abs(o[1]-c[1])==1) for c in comp}
                eps = [c for c in comp if deg[c] == 1]

                def score(ep):
                    r,c = ep
                    for o in comp:
                        if o != ep and abs(o[0]-r)+abs(o[1]-c)==1:
                            dr, dc = o[0]-r, o[1]-c
                            s = 0
                            if dr > 0: s += 2
                            if dc > 0: s += 1
                            return s
                    return 99

                best_ep = min(eps, key=score)

                for r,c in comp:
                    if (r,c) != best_ep:
                        output[r][c] = 2

    return output

