    nz = [(r,c) for r in range(h) for c in range(w) if input_grid[r][c]!=0]

    visited = set()
    comps = []
    for r,c in sorted(nz):
        if (r,c) not in visited:
            comp = []
            stack = [(r,c)]
            while stack:
                cr, cc = stack.pop()
                if (cr,cc) in visited: continue
                visited.add((cr,cc))
                comp.append((cr,cc))

                for dr,dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                    nr, nc = cr+dr, cc+dc
                    if 0 <= nr < h and 0 <= nc < w and input_grid[nr][nc]!=0:
                        if (nr,nc) not in visited:
                            stack.append((nr,nc))
            comps.append(comp)

    output = [[0]*w for _ in range(h)]

    for comp in comps:
        n = len(comp)

        if n == 1:
            # Single cell → always 2
            r,c = comp[0]
            output[r][c] = 2

        elif n == 2:
            cells_sorted = sorted(comp)
            same_col = cells_sorted[0][1] == cells_sorted[1][1]  # Vertical check

            if same_col:
                # Vertical pair: remove top, keep bottom
                output[cells_sorted[0][0]][cells_sorted[0][1]] = 0
                output[cells_sorted[1][0]][cells_sorted[1][1]] = 2
            else:
                # Horizontal pair: keep both
                for r,c in comp:
                    output[r][c] = 2

        else:
            # Size >= 3: remove endpoint that points DOWN or RIGHT
            deg = {c: sum(1 for o in comp if abs(o[0]-c[0])+abs(o[1]-c[1])==1) for c in comp}
            eps = [c for c in comp if deg[c] == 1]

            def score(ep):
                r,c = ep
                for o in comp:
                    if o != ep and abs(o[0]-r)+abs(o[1]-c)==1:
                        dr, dc = o[0]-r, o[1]-c
                        s = 0
                        if dr > 0: s += 2  # down bad
                        if dc > 0: s += 1  # right bad
                        return s
                return 99

            worst_ep = min(eps, key=score)  # Remove worst endpoint

            for r,c in comp:
                if (r,c) != worst_ep:
                    output[r][c] = 2

    return output

