                        visited.add(nb)
                        queue.append(nb)

            # Convert to tuple for hashability
            comp_tuple = tuple(sorted(comp))

            size = len(comp)
            orientation = "HORIZONTAL" if all(p[0] == comp[0][0] for p in comp) else \
                          "VERTICAL" if all(p[1] == comp[0][1] for p in comp) else "COMPLEX"
            has_bottom_edge = any(p[0] == 4 for p in comp)

            components[comp_tuple] = {
                'size': size,
                'orientation': orientation,
                'has_bottom_edge': has_bottom_edge,
                'bottom_cells': sorted([p for p in comp if p[0] == max(q[0] for q in comp)])
            }

print("Demo Components:")
for comp_tuple, props in components.items():
    print(f"  {list(comp_tuple)}: size={props['size']}, orient={props['orientation']}, bottom={props['bottom_cells']}")

expected_kept_demo = {(0,0), (1,3), (3,2), (4,2), (4,3)}

# Variant 5 check - below-is-nonzero-keeps-single
kept5 = set()
for comp_tuple, props in components.items():
